1	import { db } from "@/lib/db";
2	import { requireArea } from "@/lib/rbac";
3	import { StatusBadge } from "@/components/StatusBadge";
4	import { AbuseActions } from "@/components/admin/AbuseActions";
5	
6	export const dynamic = "force-dynamic";
7	
8	const sevBadge: Record<string, string> = { HIGH: "ERROR", MEDIUM: "PENDING", LOW: "RUNNING" };
9	
10	export default async function AdminAbuse() {
11	  await requireArea("fleet");
12	  const alerts = await db.abuseAlert.findMany({ orderBy: { createdAt: "desc" }, take: 200 });
13	
14	  // AbuseAlert stores plain serverId/userId (no relation) — resolve labels in bulk.
15	  const serverIds = [...new Set(alerts.map((a) => a.serverId))];
16	  const userIds = [...new Set(alerts.map((a) => a.userId))];
17	  const [servers, users] = await Promise.all([
18	    db.server.findMany({ where: { id: { in: serverIds } }, select: { id: true, hostname: true, status: true } }),
19	    db.user.findMany({ where: { id: { in: userIds } }, select: { id: true, email: true } }),
20	  ]);
21	  const serverMap = new Map(servers.map((s) => [s.id, s]));
22	  const userMap = new Map(users.map((u) => [u.id, u.email]));
23	
24	  const open = alerts.filter((a) => a.status === "OPEN").length;
25	
26	  return (
27	    <div>
28	      <h1 className="mb-2 text-2xl font-bold">Abuse queue</h1>
29	      <p className="mb-6 text-sm text-slate-400">
30	        Outbound-abuse alerts (bandwidth spikes / spam / scanning) raised automatically to protect IP
31	        reputation. {open} open. Thresholds: <code className="kbd">abuse_outbound_mbps</code>,{" "}
32	        <code className="kbd">abuse_autosuspend</code> in Settings.
33	      </p>
34	      {alerts.length === 0 ? (
35	        <div className="card text-sm text-slate-400">No abuse alerts. All quiet. 🟢</div>
36	      ) : (
37	        <div className="card overflow-x-auto p-0">
38	          <table className="w-full text-sm">
39	            <thead className="text-left text-slate-400">
40	              <tr>
41	                <th className="px-4 py-3">Server</th>
42	                <th className="px-4 py-3">Owner</th>
43	                <th className="px-4 py-3">Kind</th>
44	                <th className="px-4 py-3">Severity</th>
45	                <th className="px-4 py-3">Detail</th>
46	                <th className="px-4 py-3">Status</th>
47	                <th className="px-4 py-3">When</th>
48	                <th className="px-4 py-3">Actions</th>
49	              </tr>
50	            </thead>
51	            <tbody>
52	              {alerts.map((a) => {
53	                const srv = serverMap.get(a.serverId);
54	                return (
55	                  <tr key={a.id} className="border-t border-slate-800">
56	                    <td className="px-4 py-3 font-medium">{srv?.hostname ?? "—"}</td>
57	                    <td className="px-4 py-3 text-slate-400">{userMap.get(a.userId) ?? "—"}</td>
58	                    <td className="px-4 py-3">{a.kind.toLowerCase().replace(/_/g, " ")}</td>
59	                    <td className="px-4 py-3"><StatusBadge status={sevBadge[a.severity] ?? a.severity} /></td>
60	                    <td className="max-w-md px-4 py-3 text-xs text-slate-300">{a.detail}</td>
61	                    <td className="px-4 py-3">{a.status.toLowerCase()}</td>
62	                    <td className="px-4 py-3 text-slate-400">{a.createdAt.toISOString().replace("T", " ").slice(0, 19)}</td>
63	                    <td className="px-4 py-3"><AbuseActions id={a.id} status={a.status} /></td>
64	                  </tr>
65	                );
66	              })}
67	            </tbody>
68	          </table>
69	        </div>
70	      )}
71	    </div>
72	  );
73	}
