1	"use client";
2	
3	import { useActionState, useState, useTransition } from "react";
4	import { useRouter } from "next/navigation";
5	import {
6	  addNode,
7	  updateNode,
8	  setNodeEnabled,
9	  setNodeStatus,
10	  testNode,
11	  deleteNode,
12	  type TestNodeResult,
13	} from "@/lib/actions-nodes";
14	
15	type NodeValues = {
16	  id?: string;
17	  name?: string;
18	  pveNode?: string;
19	  apiUrl?: string;
20	  tokenId?: string;
21	  tokenSecret?: string;
22	  publicIp?: string;
23	  bridge?: string;
24	  subnetPrefix?: string;
25	  ipStart?: number;
26	  ipEnd?: number;
27	  sshPortStart?: number;
28	  sshPortEnd?: number;
29	  natChain?: string;
30	  storageNvme?: string;
31	  storageHdd?: string;
32	  capacityRamMB?: number;
33	  enabled?: boolean;
34	  isPrimary?: boolean;
35	  status?: "ONLINE" | "OFFLINE" | "MAINTENANCE";
36	};
37	
38	/** Suggested non-colliding defaults for a brand-new node, computed server-side. */
39	export type NodeDefaults = {
40	  ordinal: number;
41	  subnetPrefix: string;
42	  natChain: string;
43	  ipStart: number;
44	  ipEnd: number;
45	  sshPortStart: number;
46	  sshPortEnd: number;
47	};
48	
49	function Field({
50	  label,
51	  name,
52	  defaultValue,
53	  placeholder,
54	  type = "text",
55	  required = true,
56	  mono = false,
57	  hint,
58	}: {
59	  label: string;
60	  name: string;
61	  defaultValue?: string | number;
62	  placeholder?: string;
63	  type?: string;
64	  required?: boolean;
65	  mono?: boolean;
66	  hint?: string;
67	}) {
68	  return (
69	    <div>
70	      <label className="label">{label}</label>
71	      <input
72	        className={`input ${mono ? "font-mono text-xs" : ""}`}
73	        name={name}
74	        type={type}
75	        defaultValue={defaultValue}
76	        placeholder={placeholder}
77	        required={required}
78	      />
79	      {hint && <p className="mt-1 text-xs text-slate-500">{hint}</p>}
80	    </div>
81	  );
82	}
83	
84	/** Shared add/edit form. Pass `defaults` for a new node, `node` for editing. */
85	export function NodeForm({ node, defaults }: { node?: NodeValues; defaults?: NodeDefaults }) {
86	  const isEdit = Boolean(node?.id);
87	  const [state, action, pending] = useActionState(isEdit ? updateNode : addNode, {} as { error?: string; ok?: boolean });
88	
89	  const d = node ?? {};
90	  const dflt = defaults;
91	
92	  return (
93	    <form action={action} className="space-y-6">
94	      {node?.id && <input type="hidden" name="id" value={node.id} />}
95	
96	      {state?.error && (
97	        <div className="rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-400">
98	          {state.error}
99	        </div>
100	      )}
101	      {state?.ok && !state?.error && (
102	        <div className="rounded-lg border border-emerald-500/30 bg-emerald-500/10 px-3 py-2 text-sm text-emerald-300">
103	          Node saved.
104	        </div>
105	      )}
106	
107	      <section>
108	        <h3 className="section-label mb-3">Identity &amp; connection</h3>
109	        <div className="grid gap-4 sm:grid-cols-2">
110	          <Field label="Node name" name="name" defaultValue={d.name} placeholder="node-2" hint="Unique label used in the panel." />
111	          <Field label="Proxmox node (pveNode)" name="pveNode" defaultValue={d.pveNode} placeholder="ns5002570" mono hint="The hostname shown in the Proxmox UI." />
112	          <Field label="API URL" name="apiUrl" defaultValue={d.apiUrl} placeholder="https://1.2.3.4:8006" mono />
113	          <Field label="Public IP" name="publicIp" defaultValue={d.publicIp} placeholder="51.79.162.97" mono hint="The host's public IPv4 — SSH DNAT lands here." />
114	          <Field label="API token ID" name="tokenId" defaultValue={d.tokenId} placeholder="nxeon@pve!platform" mono />
115	          <Field
116	            label="API token secret"
117	            name="tokenSecret"
118	            defaultValue=""
119	            placeholder={isEdit ? "•••••• stored — leave blank to keep unchanged" : "xxxxxxxx-xxxx-xxxx-…"}
120	            mono
121	          />
122	        </div>
123	      </section>
124	
125	      <section>
126	        <h3 className="section-label mb-3">Guest network (NAT /24)</h3>
127	        <div className="grid gap-4 sm:grid-cols-3">
128	          <Field label="Bridge" name="bridge" defaultValue={d.bridge ?? "vmbr1"} placeholder="vmbr1" mono />
129	          <Field
130	            label="Subnet prefix"
131	            name="subnetPrefix"
132	            defaultValue={d.subnetPrefix ?? dflt?.subnetPrefix}
133	            placeholder="10.20.1."
134	            mono
135	            hint="Own /24 per node — trailing dot."
136	          />
137	          <Field
138	            label="NAT chain"
139	            name="natChain"
140	            defaultValue={d.natChain ?? dflt?.natChain}
141	            placeholder="NXEON_FWD_N2"
142	            mono
143	            hint="Globally unique iptables chain."
144	          />
145	          <Field label="IP start" name="ipStart" type="number" defaultValue={d.ipStart ?? dflt?.ipStart ?? 100} />
146	          <Field label="IP end" name="ipEnd" type="number" defaultValue={d.ipEnd ?? dflt?.ipEnd ?? 250} />
147	          <div className="hidden sm:block" />
148	          <Field label="SSH port start" name="sshPortStart" type="number" defaultValue={d.sshPortStart ?? dflt?.sshPortStart ?? 20000} />
149	          <Field label="SSH port end" name="sshPortEnd" type="number" defaultValue={d.sshPortEnd ?? dflt?.sshPortEnd ?? 29999} />
150	        </div>
151	      </section>
152	
153	      <section>
154	        <h3 className="section-label mb-3">Storage &amp; capacity</h3>
155	        <div className="grid gap-4 sm:grid-cols-3">
156	          <Field label="NVMe storage" name="storageNvme" defaultValue={d.storageNvme ?? "vmdata"} placeholder="vmdata" mono />
157	          <Field label="HDD storage" name="storageHdd" defaultValue={d.storageHdd ?? "vmdata-hdd"} placeholder="vmdata-hdd" mono />
158	          <Field
159	            label="RAM capacity (MB)"
160	            name="capacityRamMB"
161	            type="number"
162	            defaultValue={d.capacityRamMB ?? 56000}
163	            hint="Committable RAM ceiling for this host."
164	          />
165	        </div>
166	      </section>
167	
168	      <section>
169	        <h3 className="section-label mb-3">State</h3>
170	        <div className="flex flex-wrap items-center gap-6">
171	          <div>
172	            <label className="label">Status</label>
173	            <select className="input" name="status" defaultValue={d.status ?? "ONLINE"}>
174	              <option value="ONLINE">ONLINE</option>
175	              <option value="OFFLINE">OFFLINE</option>
176	              <option value="MAINTENANCE">MAINTENANCE</option>
177	            </select>
178	          </div>
179	          <label className="flex items-center gap-2 pt-5 text-sm">
180	            <input type="checkbox" name="enabled" defaultChecked={d.enabled ?? true} /> Enabled (accepts new servers)
181	          </label>
182	          <label className="flex items-center gap-2 pt-5 text-sm">
183	            <input type="checkbox" name="isPrimary" defaultChecked={d.isPrimary ?? false} /> Primary node
184	          </label>
185	        </div>
186	      </section>
187	
188	      <div className="flex items-center gap-3">
189	        <button className="btn-primary" disabled={pending}>
190	          {pending ? "Saving…" : isEdit ? "Save changes" : "Add node"}
191	        </button>
192	      </div>
193	    </form>
194	  );
195	}
196	
197	/** Live health-check button that surfaces the result inline. */
198	export function TestNodeButton({ id, compact = false }: { id: string; compact?: boolean }) {
199	  const [pending, start] = useTransition();
200	  const [result, setResult] = useState<TestNodeResult | null>(null);
201	
202	  const run = () => start(async () => setResult(await testNode(id)));
203	
204	  if (compact) {
205	    return (
206	      <button className="btn-secondary py-1.5" disabled={pending} onClick={run} title="Health check">
207	        {pending ? "Testing…" : "Test"}
208	      </button>
209	    );
210	  }
211	
212	  return (
213	    <div className="space-y-3">
214	      <button className="btn-secondary" disabled={pending} onClick={run}>
215	        {pending ? "Contacting Proxmox…" : "Run health check"}
216	      </button>
217	      {result && (
218	        <div
219	          className={`rounded-xl border px-4 py-3 text-sm ${
220	            result.ok
221	              ? "border-emerald-500/30 bg-emerald-500/10 text-emerald-200"
222	              : "border-red-500/30 bg-red-500/10 text-red-300"
223	          }`}
224	        >
225	          <p className="font-medium">{result.ok ? "Reachable" : "Unreachable"} — {result.message}</p>
226	          {result.ok && (
227	            <dl className="mt-2 grid grid-cols-2 gap-x-6 gap-y-1 text-xs text-slate-300 sm:grid-cols-3">
228	              {result.uptimeSec != null && (
229	                <div className="flex justify-between gap-2">
230	                  <dt className="text-slate-500">Uptime</dt>
231	                  <dd>{Math.floor(result.uptimeSec / 86400)}d {Math.floor((result.uptimeSec % 86400) / 3600)}h</dd>
232	                </div>
233	              )}
234	              {result.ramTotal != null && (
235	                <div className="flex justify-between gap-2">
236	                  <dt className="text-slate-500">RAM used</dt>
237	                  <dd>
238	                    {((result.ramUsed ?? 0) / 1024 ** 3).toFixed(1)}/{(result.ramTotal / 1024 ** 3).toFixed(0)} GB
239	                  </dd>
240	                </div>
241	              )}
242	              {result.cpu != null && (
243	                <div className="flex justify-between gap-2">
244	                  <dt className="text-slate-500">CPU</dt>
245	                  <dd>{(result.cpu * 100).toFixed(1)}%</dd>
246	                </div>
247	              )}
248	              {result.pveVersion && (
249	                <div className="flex justify-between gap-2">
250	                  <dt className="text-slate-500">PVE</dt>
251	                  <dd className="truncate">{result.pveVersion}</dd>
252	                </div>
253	              )}
254	            </dl>
255	          )}
256	          <p className="mt-2 text-[11px] text-slate-500">Checked {new Date(result.checkedAt).toLocaleTimeString()}</p>
257	        </div>
258	      )}
259	    </div>
260	  );
261	}
262	
263	export function EnableToggle({ id, enabled }: { id: string; enabled: boolean }) {
264	  const [pending, start] = useTransition();
265	  return (
266	    <button
267	      className="btn-secondary py-1.5"
268	      disabled={pending}
269	      onClick={() => start(() => setNodeEnabled(id, !enabled).then(() => {}))}
270	    >
271	      {pending ? "…" : enabled ? "Disable" : "Enable"}
272	    </button>
273	  );
274	}
275	
276	export function StatusSelect({ id, status }: { id: string; status: "ONLINE" | "OFFLINE" | "MAINTENANCE" }) {
277	  const [pending, start] = useTransition();
278	  return (
279	    <select
280	      className="input py-1.5"
281	      value={status}
282	      disabled={pending}
283	      onChange={(e) =>
284	        start(() => setNodeStatus(id, e.target.value as "ONLINE" | "OFFLINE" | "MAINTENANCE").then(() => {}))
285	      }
286	    >
287	      <option value="ONLINE">ONLINE</option>
288	      <option value="OFFLINE">OFFLINE</option>
289	      <option value="MAINTENANCE">MAINTENANCE</option>
290	    </select>
291	  );
292	}
293	
294	export function DeleteNodeButton({
295	  id,
296	  name,
297	  serverCount,
298	  isPrimary,
299	}: {
300	  id: string;
301	  name: string;
302	  serverCount: number;
303	  isPrimary: boolean;
304	}) {
305	  const router = useRouter();
306	  const [pending, start] = useTransition();
307	  const [err, setErr] = useState<string | null>(null);
308	
309	  const disabled = isPrimary || serverCount > 0;
310	  const reason = isPrimary
311	    ? "The primary node cannot be deleted."
312	    : serverCount > 0
313	      ? `${serverCount} server(s) still assigned — migrate them first.`
314	      : undefined;
