2	
3	import { revalidatePath } from "next/cache";
4	import { redirect } from "next/navigation";
5	import { z } from "zod";
6	import type { NodeStatus } from "@prisma/client";
7	import { db } from "@/lib/db";
8	import { requireAdmin } from "@/lib/auth";
9	import { pveFor } from "@/lib/proxmox";
10	
11	/**
12	 * Admin CRUD + health checks for compute nodes (Proxmox hypervisors).
13	 *
14	 * Multi-node correctness rules enforced here:
15	 *  - Each node lives in its own NAT /24 (`subnetPrefix`). Two nodes may reuse
16	 *    the same guest-IP range ONLY if they sit in different subnets — so we only
17	 *    flag an IP overlap when the subnetPrefix matches.
18	 *  - SSH DNAT forwards happen on each node's own host, so port ranges may repeat
19	 *    across different hosts. They only conflict when two Node rows point at the
20	 *    same public IP (same host) with overlapping port ranges.
21	 *  - `natChain` is the iptables chain the worker rebuilds from the DB; it must be
22	 *    globally unique so one node's rebuild never clobbers another's rules.
23	 */
24	
25	type FormState = { error?: string; ok?: boolean };
26	
27	async function audit(userId: string | null, action: string, detail?: string) {
28	  await db.auditLog.create({ data: { userId, action, detail } });
29	}
30	
31	function rangesOverlap(aStart: number, aEnd: number, bStart: number, bEnd: number): boolean {
32	  return aStart <= bEnd && bStart <= aEnd;
33	}
34	
35	/** Suggest sane, non-colliding defaults for the Nth node (1-based ordinal of the new node). */
36	export async function suggestNodeDefaults(): Promise<{
37	  ordinal: number;
38	  subnetPrefix: string;
39	  natChain: string;
40	  ipStart: number;
41	  ipEnd: number;
42	  sshPortStart: number;
43	  sshPortEnd: number;
44	}> {
45	  await requireAdmin();
46	  const count = await db.node.count();
47	  const ordinal = count + 1;
48	  // node #1 → 10.20.0. / NXEON_FWD ; node #2 → 10.20.1. / NXEON_FWD_N2 ; ...
49	  const subnetPrefix = `10.20.${ordinal - 1}.`;
50	  const natChain = ordinal === 1 ? "NXEON_FWD" : `NXEON_FWD_N${ordinal}`;
51	  return { ordinal, subnetPrefix, natChain, ipStart: 100, ipEnd: 250, sshPortStart: 20000, sshPortEnd: 29999 };
52	}
53	
54	const nodeSchema = z.object({
55	  name: z.string().min(1).max(60).regex(/^[a-zA-Z0-9._-]+$/, "Name: letters, digits, . _ - only."),
56	  pveNode: z.string().min(1).max(60).regex(/^[a-zA-Z0-9.-]+$/, "Invalid Proxmox node name."),
57	  apiUrl: z.string().url().max(200).refine((u) => u.startsWith("http"), "API URL must be http(s)."),
58	  tokenId: z.string().min(1).max(120).regex(/^[^\s]+![^\s]+$/, "Token ID looks like user@realm!tokenname."),
59	  tokenSecret: z.string().min(1).max(200),
60	  publicIp: z.string().min(1).max(60),
61	  bridge: z.string().min(1).max(20).regex(/^[a-z0-9]+$/, "Bridge: e.g. vmbr1."),
62	  subnetPrefix: z
63	    .string()
64	    .regex(/^\d{1,3}\.\d{1,3}\.\d{1,3}\.$/, "Subnet prefix must be a /24 like 10.20.1. (trailing dot)."),
65	  ipStart: z.coerce.number().int().min(2).max(254),
66	  ipEnd: z.coerce.number().int().min(2).max(254),
67	  sshPortStart: z.coerce.number().int().min(1024).max(65535),
68	  sshPortEnd: z.coerce.number().int().min(1024).max(65535),
69	  natChain: z.string().min(1).max(40).regex(/^[A-Z0-9_]+$/, "NAT chain: UPPERCASE letters, digits, _ only."),
70	  storageNvme: z.string().min(1).max(60),
71	  storageHdd: z.string().min(1).max(60),
72	  capacityRamMB: z.coerce.number().int().min(1024).max(4_000_000),
73	  enabled: z.boolean().default(true),
74	  isPrimary: z.boolean().default(false),
75	  status: z.enum(["ONLINE", "OFFLINE", "MAINTENANCE"]).default("ONLINE"),
76	});
77	
78	type NodeInput = z.infer<typeof nodeSchema>;
79	
80	function parseNodeForm(formData: FormData) {
81	  return nodeSchema.safeParse({
82	    name: (formData.get("name") ?? "").toString().trim(),
83	    pveNode: (formData.get("pveNode") ?? "").toString().trim(),
84	    apiUrl: (formData.get("apiUrl") ?? "").toString().trim(),
85	    tokenId: (formData.get("tokenId") ?? "").toString().trim(),
86	    tokenSecret: (formData.get("tokenSecret") ?? "").toString().trim(),
87	    publicIp: (formData.get("publicIp") ?? "").toString().trim(),
88	    bridge: (formData.get("bridge") ?? "vmbr1").toString().trim(),
89	    subnetPrefix: (formData.get("subnetPrefix") ?? "").toString().trim(),
90	    ipStart: formData.get("ipStart"),
91	    ipEnd: formData.get("ipEnd"),
92	    sshPortStart: formData.get("sshPortStart"),
93	    sshPortEnd: formData.get("sshPortEnd"),
94	    natChain: (formData.get("natChain") ?? "").toString().trim(),
95	    storageNvme: (formData.get("storageNvme") ?? "vmdata").toString().trim(),
96	    storageHdd: (formData.get("storageHdd") ?? "vmdata-hdd").toString().trim(),
97	    capacityRamMB: formData.get("capacityRamMB"),
98	    enabled: formData.get("enabled") != null,
99	    isPrimary: formData.get("isPrimary") != null,
100	    status: (formData.get("status") ?? "ONLINE").toString(),
101	  });
102	}
103	
104	/**
105	 * Validate a proposed node's ranges/uniqueness against all other nodes.
106	 * `selfId` excludes the row being edited. Returns an error string or null.
107	 */
108	async function validateAgainstExisting(data: NodeInput, selfId?: string): Promise<string | null> {
109	  if (data.ipEnd < data.ipStart) return "Guest IP range invalid: ipEnd must be ≥ ipStart.";
110	  if (data.sshPortEnd < data.sshPortStart) return "SSH port range invalid: end must be ≥ start.";
111	
112	  const others = await db.node.findMany({
113	    where: selfId ? { id: { not: selfId } } : {},
114	    select: {
115	      name: true,
116	      publicIp: true,
117	      subnetPrefix: true,
118	      ipStart: true,
119	      ipEnd: true,
120	      sshPortStart: true,
121	      sshPortEnd: true,
122	      natChain: true,
123	      isPrimary: true,
124	    },
125	  });
126	
127	  for (const o of others) {
128	    if (o.natChain === data.natChain) {
129	      const next = data.natChain === "NXEON_FWD" ? "NXEON_FWD_N2" : `${data.natChain}_X`;
130	      return `NAT chain "${data.natChain}" is already used by node "${o.name}". Each node needs a globally unique chain (e.g. ${next}).`;
131	    }
132	    // IP ranges only collide inside the same /24 subnet.
133	    if (o.subnetPrefix === data.subnetPrefix && rangesOverlap(data.ipStart, data.ipEnd, o.ipStart, o.ipEnd)) {
134	      return `Guest IP range ${data.subnetPrefix}${data.ipStart}-${data.ipEnd} overlaps node "${o.name}" (${o.subnetPrefix}${o.ipStart}-${o.ipEnd}). Give this node its own /24, e.g. bump subnetPrefix to 10.20.N.`;
135	    }
136	    // SSH ports only collide when two nodes share the same public host.
137	    if (
138	      o.publicIp === data.publicIp &&
139	      rangesOverlap(data.sshPortStart, data.sshPortEnd, o.sshPortStart, o.sshPortEnd)
140	    ) {
141	      return `SSH port range ${data.sshPortStart}-${data.sshPortEnd} overlaps node "${o.name}" on the same host ${data.publicIp}. Use a distinct port range for co-hosted nodes.`;
142	    }
143	    if (data.isPrimary && o.isPrimary) {
144	      return `Node "${o.name}" is already the primary. Only one node can be primary.`;
145	    }
146	  }
147	  return null;
148	}
149	
150	export async function addNode(_prev: FormState, formData: FormData): Promise<FormState> {
151	  const admin = await requireAdmin();
152	  const parsed = parseNodeForm(formData);
153	  if (!parsed.success) return { error: parsed.error.issues[0]?.message ?? "Invalid node details." };
154	  const data = parsed.data;
155	
156	  if (await db.node.findUnique({ where: { name: data.name } })) {
157	    return { error: `A node named "${data.name}" already exists.` };
