26	/** Suspend the server behind an alert (enqueues a SUSPEND job) and mark it ACTIONED. */
27	export async function suspendForAbuse(id: string): Promise<{ ok?: boolean; error?: string }> {
28	  const admin = await requireArea("fleet");
29	  const alert = await db.abuseAlert.findUnique({ where: { id } });
30	  if (!alert) return { error: "Alert not found." };
31	  const server = await db.server.findUnique({ where: { id: alert.serverId } });
32	  if (!server) return { error: "Server no longer exists." };
33	  if (server.status !== "SUSPENDED") {
34	    // Record WHY before enqueuing. Without it the billing engine cannot tell an
35	    // abuse suspension from an unpaid one, and two things go wrong: the overdue
36	    // sweep eventually DELETES the server as a non-payer (the renewal sweep skips
37	    // suspended servers, so it was never billed or warned in the meantime), and
38	    // the customer can lift the suspension themselves by clicking "Renew now".
39	    await db.server.update({
40	      where: { id: server.id },
41	      data: {
42	        suspendReason: "ABUSE",
43	        suspendedNote: "suspended pending an abuse review — contact support",
44	      },
45	    });
46	    await db.job.create({ data: { type: "SUSPEND", serverId: server.id } });
47	  }
48	  await db.abuseAlert.update({ where: { id }, data: { status: "ACTIONED" } });
49	  await db.auditLog.create({
50	    data: { userId: admin.id, action: "abuse.suspend", detail: `${server.hostname} (${alert.kind}) — ${alert.detail}` },
51	  });
52	  revalidatePath("/admin/abuse");
53	  return { ok: true };
54	}
